from pathlib import Path
import pandas as pd,numpy as np,json
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent;O=R/'results'
D=pd.read_csv(O/'distribution_summary.csv');H=pd.read_csv(O/'histograms.csv');B=pd.read_csv(O/'distance_bins.csv');A=pd.read_csv(O/'distance_adjusted.csv')
colors={'helped':'#17845d','harmed':'#ce514c','unchanged':'#6c7c90'};names={'helped':'Helpful','harmed':'Harmful','unchanged':'Unchanged'};labels={'labelled_similarity':'Labelled similarity','important_contrast':'Important contrast'}
plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False,'savefig.dpi':170})
for metric,filename,axis in [('nearest_cosine','cosine_distributions','Cosine similarity  →  more similar'),('cosine_rank','relative_distributions','Similarity percentile within backbone × dataset  →  closer')]:
 fig,axes=plt.subplots(2,2,figsize=(12,8),sharex=True,sharey=True)
 for r,lab in enumerate(labels):
  for c,lev in enumerate(['yes','no']):
   ax=axes[r,c]
   for ev in colors:
    h=H[(H.policy=='judge50_direct')&(H.label==lab)&(H.level==lev)&(H.outcome==ev)&(H.metric==metric)]
    # Bin mass, with each curve independently normalized: shape rather than event frequency.
    xx=(h.left+h.right)/2;ax.step(xx.to_numpy(),h.mass.to_numpy()*100,where='mid',color=colors[ev],label=names[ev],linewidth=2)
   ax.set_title(labels[lab]+' = '+lev.upper());ax.grid(alpha=.16);ax.set_xlim(0,1)
   if r==1:ax.set_xlabel(axis)
   if c==0:ax.set_ylabel('Weighted observations within group (%)')
 axes[0,0].legend(frameon=False);fig.suptitle('How close are neighbours when NN explanations help or hurt?',fontsize=17,y=.99)
 fig.text(.5,.01,'Original control vs NN decisions at judge threshold 50 • Majority annotation • Each distribution sums to 100%',ha='center',fontsize=10)
 fig.tight_layout(rect=[0,.04,1,.95]);fig.savefig(O/(filename+'.png'));fig.savefig(O/(filename+'.pdf'));plt.close(fig)
fig,axes=plt.subplots(1,2,figsize=(12,4.8))
for ax,metric,title in zip(axes,['harm_among_flips','gain'],['Among changed decisions: how often is the flip harmful?','Across all decisions: net NN accuracy gain']):
 for lev,col in [('yes','#9355b4'),('no','#d69b2b')]:
  b=B[(B.policy=='judge50_direct')&(B.annotator=='majority')&(B.label=='important_contrast')&(B.level==lev)&(B.metric==metric)].sort_values('bin')
  ax.plot(b.bin.to_numpy(),b['mean'].to_numpy()*100,'o-',color=col,label='Contrast '+lev.upper());ax.fill_between(b.bin.to_numpy(),b.lo.to_numpy()*100,b.hi.to_numpy()*100,color=col,alpha=.14)
 ax.set_title(title,fontsize=12);ax.set_xticks([1,2,3,4,5]);ax.set_xticklabels(['Farthest','2','3','4','Closest']);ax.set_xlabel('Similarity quintile within backbone × dataset');ax.grid(alpha=.18);ax.legend(frameon=False)
axes[0].set_ylabel('Harmful flips / all flips (%)');axes[1].set_ylabel('Helped − harmed (percentage points)');axes[1].axhline(0,color='black',lw=.7)
fig.suptitle('Does distance account for the contrast pattern?',fontsize=17);fig.tight_layout(rect=[0,0,1,.94]);fig.savefig(O/'contrast_distance.png');fig.savefig(O/'contrast_distance.pdf');plt.close(fig)
main=D.query("policy=='judge50_direct' and annotator=='majority' and metric=='nearest_cosine'")[['label','level','outcome','n','mean','median','q25','q75']]
reg=A.query("policy=='judge50_direct' and annotator=='majority'").copy()
for k in ['contrast_yes_coefficient','lo','hi']:reg[k]=reg[k]*100
html='''<!doctype html><html><head><meta charset="utf-8"><title>NN distance and outcomes</title><style>body{font:17px system-ui;max-width:1180px;margin:40px auto;color:#182337;padding:0 20px;line-height:1.55}img{width:100%}table{border-collapse:collapse;font-size:14px}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:right}th{background:#eef3f8}h2{margin-top:42px}.note{background:#edf3f8;padding:18px;border-radius:10px}</style></head><body><h1>Nearest-neighbour distance: helpful, harmful and unchanged decisions</h1><p>Original control versus NN classification at a common judge cutoff of 50, without probe gating. Labels are the majority vote of Qwen122, Gemma31B and Qwen27B. Helpful means wrong → correct; harmful means correct → wrong; unchanged includes both stable correct and stable wrong.</p><div class="note">240,524 paired original judge–context decisions across 25,000 contexts and 15,915 distinct target-text clusters. We preserve design weights and equal original judge/backbone/dataset cell mass. Each distribution below is independently normalized; curve heights describe shape, not the relative number of helpful/harmful/unchanged events. Labels can co-occur. Uncertain or unresolved labels are excluded separately for each label.</div><h2>What this shows</h2><p>Distance alone does not account for the pooled contrast pattern: within the same judge/backbone/dataset cells, contrast YES is associated with a 24.00-point higher harmful share among flips, versus 23.95 points after distance adjustment. Adding neighbour/target label alignment and target class reduces this to 1.60 points; adding the similarity annotation too reduces it to 1.14 points (95% CI −0.51 to 2.79). This is an exploratory association, not a causal explanation.</p><p>Among contrast-YES examples, weighted mean cosine is 0.494 for helpful, 0.480 for harmful and 0.489 for unchanged decisions: substantial overlap, rather than clearly separated distance regimes.</p><h2>Raw cosine similarity</h2><img src="cosine_distributions.png"><p>Higher cosine means more similar embeddings. It is target-to-neighbour similarity, not distance to the probe decision boundary. Different embedding models can have different cosine scales.</p><h2>Comparable relative closeness</h2><img src="relative_distributions.png"><p>Percentile ranks are computed within each backbone and dataset test split, using the full sampled contexts. This reduces differences in cosine scales across embedding spaces and datasets; it does not remove every compositional difference.</p><h2>Contrast at similar distances</h2><img src="contrast_distance.png"><p>Shaded bands are 95% target-text-cluster intervals. Left: harmful share among flips. Right: net gain across all decisions, including unchanged. These have different denominators. Within-quintile comparisons are descriptive and do not hold every other feature constant.</p><h2>Distance-adjusted comparisons</h2><p>The contrast-YES coefficient below is a percentage-point difference from contrast-NO. All comparisons hold the original judge/backbone/dataset cell constant. The next specification also adjusts for cubic raw cosine and relative similarity rank; the additional specifications add the similarity label, neighbour/target gold-label alignment plus target class, or both. The outcome is either net accuracy gain over all decisions or harmful probability among flips. These linear associations and clustered intervals do not establish causality or mediation.</p>'''+reg[['outcome','spec','contrast_yes_coefficient','lo','hi']].round(3).to_html(index=False)+'''<h2>Weighted distribution summaries</h2>'''+main.round(4).to_html(index=False)+'''<h2>Reproducibility and sensitivity</h2><p>Saved CSVs include each annotation judge separately, fixed probe50/judge50 pipeline decisions, and the prior three-anchor shared-threshold tuning average. Anchor-average outcomes are fractional averages of three actual binary events, not thresholded average probabilities. No new model calls or threshold fitting.</p><ul>'''+''.join('<li><a href="'+f+'">'+f+'</a></li>' for f in ['distribution_summary.csv','distance_bins.csv','distance_adjusted.csv','COMPLETED.json','cosine_distributions.pdf','relative_distributions.pdf','contrast_distance.pdf'])+'</ul></body></html>'
(O/'report.html').write_text(html)
print(main.to_string(index=False));print(reg.to_string(index=False))
